  ['border', '1px solid red'],
  ['border', 'red'],
  ['border-top', '1px solid red'],
  ['outline', '2px dashed blue'],
  ['overflow', 'hidden'],
  ['overflow', 'hidden auto'],
  ['gap', '10px'],
  ['gap', '10px 20px'],
  ['flex-flow', 'row wrap'],
  ['flex-flow', 'wrap'],
  ['text-decoration', 'underline'],
